<div class="studio-modal" id="visit-occurrence-modal" data-studio-modal aria-hidden="true"><div class="studio-modal-dialog"><header class="studio-modal-header"><div><p class="studio-eyebrow">Durante a visita</p><h2 class="studio-modal-title">Registrar ocorrência</h2></div><button class="studio-modal-close" type="button" data-studio-modal-close aria-label="Fechar">×</button></header><form class="studio-form studio-modal-body" action="<?= url('/operation/visitas/'.$visit->id) ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="occurrence"><div class="studio-grid studio-grid-2"><label>Categoria<input name="category" required placeholder="Ex.: Segurança"></label><label>Prioridade<select name="priority"><option value="medium">Média</option><option value="low">Baixa</option><option value="high">Alta</option><option value="critical">Crítica</option></select></label><label>Encaminhar como<select name="outcome_type"><option value="issue">Pendência</option><option value="demand">Demanda</option><option value="ticket">Chamado</option><option value="task">Tarefa</option><option value="record">Somente registro</option></select></label><label>Prazo<input type="datetime-local" name="due_at"></label></div><label>Título<input name="title" minlength="3" required></label><label>Descrição<textarea name="description" rows="5"></textarea></label><footer class="studio-modal-footer"><button class="studio-btn" type="button" data-studio-modal-close>Cancelar</button><button class="studio-btn primary">Registrar e encaminhar</button></footer></form></div></div>
