<?php $this->start('scripts') ?><script>
(()=>{const geolocate=()=>new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),reject,{enableHighAccuracy:true,timeout:12000,maximumAge:15000}):reject(new Error('Localização indisponível')));const fillLocation=(form,position)=>{['latitude','longitude','accuracy'].forEach(key=>{if(form.elements[key])form.elements[key].value=position[key]??''});if(form.elements.device)form.elements.device.value=navigator.userAgent};document.querySelector('[data-visit-start]')?.addEventListener('click',async()=>{const form=document.querySelector('[data-visit-start-form]');try{fillLocation(form,await geolocate());form.requestSubmit()}catch(error){window.StudioFeedback?.show?.('Autorize a localização para iniciar a visita.','warning')}});document.querySelectorAll('[data-evidence-for]').forEach(button=>button.addEventListener('click',async()=>{const modal=document.querySelector('#visit-evidence-modal'),form=modal.querySelector('form');form.elements.item_id.value=button.dataset.evidenceFor||'';try{fillLocation(form,await geolocate())}catch(error){}window.StudioModal?.get(modal)?.open()}));
const pad=document.querySelector('[data-signature-pad]');let signed=false;if(pad){const context=pad.getContext('2d');context.lineWidth=2.5;context.lineCap='round';context.strokeStyle='#172033';let drawing=false;const point=event=>{const rect=pad.getBoundingClientRect(),touch=event.touches?.[0]||event;return{x:(touch.clientX-rect.left)*(pad.width/rect.width),y:(touch.clientY-rect.top)*(pad.height/rect.height)}};const start=event=>{event.preventDefault();drawing=true;signed=true;const p=point(event);context.beginPath();context.moveTo(p.x,p.y)};const move=event=>{if(!drawing)return;event.preventDefault();const p=point(event);context.lineTo(p.x,p.y);context.stroke()};const end=()=>drawing=false;pad.addEventListener('pointerdown',start);pad.addEventListener('pointermove',move);window.addEventListener('pointerup',end);pad.addEventListener('touchstart',start,{passive:false});pad.addEventListener('touchmove',move,{passive:false});pad.addEventListener('touchend',end);document.querySelector('[data-signature-clear]')?.addEventListener('click',()=>{context.clearRect(0,0,pad.width,pad.height);signed=false})}
document.querySelector('#visit-finish-modal form')?.addEventListener('submit',async event=>{const form=event.currentTarget;if(pad){if(!signed){event.preventDefault();window.StudioFeedback?.show('Faça a assinatura antes de concluir.','warning');return}form.elements.signature_data.value=pad.toDataURL('image/png')}if(!form.elements.latitude.value){event.preventDefault();try{fillLocation(form,await geolocate());form.requestSubmit()}catch(error){form.requestSubmit()}}});document.querySelectorAll('[data-visit-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-visit-tab]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('[data-visit-panel]').forEach(panel=>panel.hidden=panel.dataset.visitPanel!==button.dataset.visitTab)}));const queueKey='operation-visit-queue';const queue=()=>JSON.parse(localStorage.getItem(queueKey)||'[]');document.querySelectorAll('.operation-check-form').forEach(form=>form.addEventListener('submit',event=>{if(navigator.onLine)return;event.preventDefault();const values=Object.fromEntries(new FormData(form).entries());values.sync_id=crypto.randomUUID();const pending=queue();pending.push({url:form.action,values});localStorage.setItem(queueKey,JSON.stringify(pending));window.StudioFeedback?.show('Resposta salva no aparelho. Ela será sincronizada quando a conexão voltar.','warning')}));const sync=async()=>{const pending=queue(),remaining=[];for(const item of pending){try{const body=new FormData();Object.entries(item.values).forEach(([key,value])=>body.append(key,value));const response=await fetch(item.url,{method:'POST',body,headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error('sync')}catch(error){remaining.push(item)}}localStorage.setItem(queueKey,JSON.stringify(remaining));if(pending.length&&!remaining.length){window.StudioFeedback?.show('Dados offline sincronizados.','success');location.reload()}};window.addEventListener('online',sync);if(navigator.onLine)sync()})();
</script><?php $this->stop() ?>
